    'RegisterSimpleRisk'=>'Giấy Đăng Ký SimpleRisk',
    'RegistrationText'=>'Các phiên bản SimpleRisk đã đăng ký ngay lập tức được cấp quyền truy cập vào Các tính năng bổ sung của Khung kiểm soát bảo mật và nâng cấp (SCF). Upgrade Extra cung cấp khả năng sao lưu và nâng cấp phiên bản SimpleRisk của bạn chỉ bằng một nút bấm. Khung kiểm soát an toàn (SCF) Extra cung cấp một khung kiểm soát chung được tích hợp vào chức năng Quản trị rủi ro đơn giản. Khi đăng ký SimpleRisk, thông tin đăng ký của bạn sẽ được gửi đến máy chủ do SimpleRisk lưu trữ. Thông tin đăng ký được cung cấp sẽ được SimpleRisk sử dụng để thông báo cho khách hàng về các bản phát hành và cập nhật bảo mật mới. Hành động đăng ký SimpleRisk sẽ chọn bạn tham gia các thông tin tiếp thị của chúng tôi, nhưng bạn có thể chọn không tham gia bất kỳ lúc nào bằng cách sử dụng liên kết hủy đăng ký trong các thông tin liên lạc này. SimpleRisk tôn trọng quyền riêng tư của khách hàng và thông tin được cung cấp cho chúng tôi thông qua quy trình đăng ký SimpleRisk sẽ không bao giờ được bán cho bên thứ ba.',
