    'QueueMonitorDesc'                    => 'Kiểm tra hàng đợi các tác vụ nền: các tác vụ đang chờ xử lý, đang thực hiện và bị lỗi.',
    'ExtrasDesc'                          => 'Kích hoạt, vô hiệu hóa và cấu hình SimpleRisk Extras (các tiện ích bổ sung trả phí).',
    'ArtificialIntelligenceExtraDesc'     => 'Gói Trí tuệ Nhân tạo bổ sung cung cấp khả năng phân tích rủi ro nâng cao (bao gồm cả đánh giá FAIR) và tài liệu tùy chỉnh.',
    'CustomizationExtraDesc'              => 'Tính năng Tùy chỉnh bổ sung cho phép thêm và xóa các loại trường khác nhau cũng như tạo động các mẫu trang tùy chỉnh.',
    'NotificationExtraDesc'               => 'Tiện ích Email Notification Extra cho phép SimpleRisk gửi thông báo qua email khi rủi ro được gửi, sửa đổi hoặc được xử lý theo bất kỳ cách nào khác. Tiện ích này cũng có thể được thêm vào dưới dạng một tập lệnh theo lịch trình để gửi lời nhắc định kỳ khi rủi ro sẵn sàng để được quản lý xem xét. Trong sản phẩm SimpleRisk Core, nếu không có tiện ích này, sẽ không có thông báo nào được gửi ra ngoài công cụ.',
    'VulnerabilityManagementExtraDesc'    => 'Gói Vulnerability Management Extra cung cấp cho khách hàng khả năng tích hợp phiên bản SimpleRisk của họ với Qualys, Tenable.io hoặc Rapid7 Nexpose/InsightVM và nhập cả dữ liệu tài sản và lỗ hổng vào SimpleRisk. Từ đó, bạn có thể chọn các trang web muốn giám sát, xác định điểm số lỗ hổng nào cần được nhập và phân loại các lỗ hổng nào được chuyển thành rủi ro để theo dõi.',
    'IncidentManagementExtraDesc'         => 'Gói Incident Management Extra dựa trên Hướng dẫn Xử lý Sự cố An ninh Máy tính NIST 800-61 và cung cấp các khả năng quản lý sự cố ngay trong hệ thống SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'Đổi tên các thuật ngữ của SimpleRisk (Rủi ro, Tài sản, Khung, v.v.) trên toàn bộ giao diện người dùng.',
    'RiskConfigurationDesc'               => 'Thiết lập các quy tắc chấm điểm rủi ro: cấp độ, mức độ chấp nhận, ngưỡng SLA và các công thức rủi ro cổ điển/đóng góp.',
    'RiskAndThreatCatalogDesc'            => 'Duy trì danh mục các giá trị rủi ro và mối đe dọa được sử dụng trong các menu thả xuống.',
    'AddAndRemoveValuesDesc'              => 'Quản lý các giá trị trong menu thả xuống cho các trường rủi ro: vị trí, nguồn gốc, danh mục, nhóm, công nghệ, v.v.',
    'AssetValuationDesc'                  => 'Cấu hình thang giá trị tài sản và các thiết lập ghi đè giá trị cho từng tài sản.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'Thêm, chỉnh sửa, vô hiệu hóa và đặt lại mật khẩu người dùng; quản lý chính sách mật khẩu.',
    'RoleManagementDesc'                  => 'Xác định các vai trò và quyền hạn mà mỗi vai trò được cấp.',
    'TeamManagementDesc'                  => 'Tạo và quản lý các nhóm được sử dụng để lọc thông tin hiển thị hồ sơ.',
    'SeparationExtraDesc'                 => 'Tính năng Phân tách theo nhóm (Team-Based Separation Extra) giới hạn việc xem rủi ro chỉ cho những người dùng là thành viên của nhóm được giao rủi ro đó. Trong sản phẩm SimpleRisk Core, nếu không có tính năng này, mọi người dùng đều có thể xem mọi rủi ro.',
    'CustomAuthenticationExtraDesc'       => 'Gói Custom Authentication Extra hỗ trợ xác thực Active Directory và SAML. Trong sản phẩm SimpleRisk Core, nếu không có gói Extra này, lựa chọn duy nhất là tạo người dùng mới trong kho lưu trữ danh tính SimpleRisk.',
    'EncryptionExtraDesc'                 => 'Tiện ích Encrypted Database Extra tạo ra một khóa mã hóa AES-256 bit ngẫu nhiên, sau đó sử dụng khóa này để mã hóa văn bản nhạy cảm trước khi chèn vào cơ sở dữ liệu SimpleRisk. Điều này ngăn chặn bất kỳ ai xem hoặc sửa đổi dữ liệu mà không sử dụng trực tiếp ứng dụng SimpleRisk.',
    'OrganizationManagementDesc'          => "Tính năng Phân cấp Tổ chức bổ sung cho phép định nghĩa nhiều Đơn vị Kinh doanh, mỗi đơn vị có thể bao gồm bất kỳ số lượng nhóm nào. Sau đó, người dùng có thể được chỉ định vào một hoặc nhiều nhóm thuộc các Đơn vị Kinh doanh khác nhau. Điều này ảnh hưởng đến khả năng người dùng xem và sử dụng các nhóm, người dùng và tài sản mà họ không được liên kết.",

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'Xóa hàng loạt tiềm ẩn nhiều rủi ro. Hãy sử dụng một cách tiết kiệm — việc xóa là vĩnh viễn.',
    'AuditTrailDesc'                      => 'Tìm kiếm và xuất nhật ký kiểm toán hệ thống về các hành động của người dùng.',
    'ImportExportExtraDesc'               => 'Tiện ích Import-Export Extra cho phép nhập dữ liệu vào SimpleRisk bằng cách ánh xạ các trường trong tệp CSV với các trường trong cơ sở dữ liệu SimpleRisk. Nó có thể được sử dụng để nhập kết quả kiểm toán từ bảng tính của bên thứ ba, kết quả quét lỗ hổng từ công cụ khác, tài sản từ CMDB của bạn và nhiều hơn nữa. Tiện ích Extra cũng cung cấp khả năng xuất các tệp CSV từ SimpleRisk chứa Rủi ro, Biện pháp giảm thiểu, Đánh giá hoặc báo cáo kết hợp của cả ba.',
    'JiraExtraDesc'                       => 'Tiện ích Jira Integration Extra cung cấp cho người dùng khả năng tích hợp hai chiều với một phiên bản Jira. Nó cho phép kết nối các rủi ro với các vấn đề trong Jira, cũng như đồng bộ hóa dữ liệu, trạng thái và bình luận của chúng.',
    'APIExtraDesc'                        => 'API Extra cho phép khách hàng sử dụng API RESTful để tạo các tương tác theo kịch bản với các ứng dụng khác nhằm đạt được khả năng tự động hóa nâng cao và tận dụng cơ sở hạ tầng hiện có.',
    'AdvancedSearchExtraDesc'             => "Tính năng Tìm kiếm Nâng cao mở rộng chức năng của hộp tìm kiếm trên thanh công cụ phía trên, cho phép tìm kiếm rủi ro bằng cách tìm kiếm văn bản trong dữ liệu rủi ro.",
    'AssessmentsExtraDesc'                => 'Tiện ích Risk Assessment Extra cung cấp cho người dùng khả năng xác định người liên hệ, tạo câu hỏi (bao gồm cả logic), tập hợp nhiều câu hỏi bằng mẫu bảng câu hỏi, tạo bảng câu hỏi và gửi chúng cho người liên hệ, xem kết quả bảng câu hỏi, thêm rủi ro dựa trên các kết quả đó và so sánh kết quả theo thời gian, nhập và xuất các đánh giá tùy chỉnh từ bên ngoài, và xem lại nhật ký kiểm toán đánh giá rủi ro.',
    'ActiveAssessmentsDesc'               => 'Xem và quản lý các bài đánh giá đang diễn ra.',
    'WorkflowsExtraDesc'                  => 'Tiện ích Workflows Extra cung cấp một công cụ quản lý quy trình làm việc trực quan, dựa trên sự kiện, tự động hóa các hành động quản lý rủi ro khi xảy ra các sự kiện trong SimpleRisk. Bạn có thể thiết kế các quy trình làm việc được kích hoạt khi có thay đổi — chẳng hạn như rủi ro được gửi, cập nhật hoặc xem xét — để định tuyến phê duyệt, phân công công việc và duy trì quy trình hoạt động mà không cần can thiệp thủ công.',

    // Configure Hub - tile descriptions (frameworks category)
    'UCFExtraDesc'                        => 'Unified Compliance Framework (UCF) Extra là một tích hợp cấp API giữa Unified Compliance Framework và SimpleRisk. Kích hoạt tính năng này cho phép bạn nhập các khung và ánh xạ kiểm soát đã chọn trực tiếp từ UCF.',
    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extra là sự tích hợp trực tiếp giữa Secure Controls Framework và SimpleRisk. Nó nhập danh mục các biện pháp kiểm soát của SCF và các ánh xạ của chúng trên nhiều khuôn khổ tuân thủ và an ninh mạng vào chức năng Quản trị của SimpleRisk, cho phép bạn áp dụng các khuôn khổ cần thiết và quản lý các biện pháp kiểm soát mà không cần phải tự xây dựng chúng.",

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => 'Chuyển đổi các cột ngày xem xét kiểu varchar cũ sang kiểu dữ liệu ngày tháng phù hợp. Chỉ hiển thị khi cần thiết.',
    'FixFileEncodingIssuesDesc'           => 'Sửa chữa các tệp tải lên có vấn đề về mã hóa ký tự. Chỉ hiển thị khi cần thiết.',
    'DatabaseUpgradeDesc'                 => 'Kích hoạt thủ công quy trình nâng cấp cơ sở dữ liệu SimpleRisk.',

