    'Help' => 'Giúp đỡ',
    'Profile' => 'Hồ sơ',
    'Scoring' => 'Ghi điểm',
    'EncryptionMissingLockTablesPrivilege'   => 'Người dùng cơ sở dữ liệu SimpleRisk không có quyền LOCK TABLES, quyền này cần thiết để mã hóa cơ sở dữ liệu một cách an toàn. Hãy nhờ quản trị viên cơ sở dữ liệu chạy câu lệnh GRANT được trả về trong phản hồi và thử lại.',
    'EncryptionMissingLockTablesPrivilegeUi' => 'Người dùng cơ sở dữ liệu SimpleRisk không có quyền LOCK TABLES cần thiết cho việc mã hóa. Quản trị viên cơ sở dữ liệu phải chạy lệnh: GRANT LOCK TABLES ON {$db}.* TO {$user}; sau đó thử lại.',
    'EncryptionRequiredGrantLabel' => 'Yêu cầu về bản tuyên bố tài trợ:',
    'EncryptionActivationAlreadyRunning' => 'Quá trình kích hoạt mã hóa đang được tiến hành. Hãy đợi cho đến khi hoàn tất hoặc sử dụng chức năng khôi phục từ bản sao lưu để phục hồi.',
    'EncryptionActivationEnqueued'           => 'Quá trình kích hoạt mã hóa bổ sung đã được xếp vào hàng chờ. Giao diện quản trị sẽ theo dõi tiến trình trong khi cơ sở dữ liệu đang được mã hóa.',
    'EncryptionActivationEnqueueFailed'      => 'Không thể thêm tác vụ kích hoạt mã hóa vào hàng đợi. Vui lòng kiểm tra nhật ký gỡ lỗi để biết thêm chi tiết.',
    'EncryptionDeactivationEnqueued'         => 'Quá trình vô hiệu hóa tính năng Mã hóa bổ sung đã được xếp vào hàng chờ. Giao diện quản trị sẽ theo dõi tiến trình trong khi cơ sở dữ liệu được giải mã.',
    'EncryptionDeactivationEnqueueFailed'    => 'Không thể thêm tác vụ vô hiệu hóa mã hóa vào hàng đợi. Vui lòng kiểm tra nhật ký gỡ lỗi để biết thêm chi tiết.',
    'EncryptionPipelineInProgress'           => 'Quá trình mã hóa (kích hoạt, vô hiệu hóa hoặc khôi phục) hiện đang diễn ra. Vui lòng chờ cho đến khi quá trình hoàn tất trước khi thử lại.',
    'EncryptionPipelineInProgressTask'       => 'Một quy trình mã hóa hiện đang được tiến hành (tác vụ #{id}, {type}). Hãy đợi cho đến khi nó hoàn tất trước khi thử lại.',
    'EncryptionInFlightTitle'            => 'Quá trình mã hóa đang diễn ra',
    'EncryptionInFlightBody'             => 'Hiện đang chạy một quy trình kích hoạt, vô hiệu hóa hoặc khôi phục mã hóa. Vui lòng đợi cho đến khi quy trình hoàn tất — trang sẽ tự động làm mới khi thao tác hoàn thành — trước khi thử lại.',
    'OK'                                 => 'ĐƯỢC RỒI',
    'ActivationGuardFailed'                 => 'Quá trình kích hoạt không thể bắt đầu. Xem thông báo ở đầu trang để biết thêm chi tiết.',
    'EncryptionStageStarting'               => 'Bắt đầu…',
    'EncryptionStageProgress'               => 'Giai đoạn {current} của {total}: {name}',
    'EncryptionStageAllDone'                => 'Tất cả các giai đoạn đã hoàn tất.',
