    'EncryptionActivationFailedTitle'       => 'Kích hoạt mã hóa thất bại',
    'EncryptionActivationFailedBody'        => 'Quá trình kích hoạt không thể hoàn tất và cơ sở dữ liệu có thể đang ở trạng thái không nhất quán. Bản sao lưu trước khi kích hoạt vẫn được giữ lại — hãy sử dụng chức năng Khôi phục từ bản sao lưu để khôi phục hoặc liên hệ với bộ phận hỗ trợ của SimpleRisk.',
