    'EncryptionDeactivationFailedBody'      => 'Quá trình vô hiệu hóa không thể hoàn tất và cơ sở dữ liệu có thể đang ở trạng thái không nhất quán. Bản sao lưu ở trạng thái mã hóa vẫn được giữ lại — hãy sử dụng chức năng Khôi phục từ bản sao lưu để khôi phục về trạng thái mã hóa, hoặc liên hệ với bộ phận hỗ trợ của SimpleRisk.',
